({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({ALT_TEXT:"Alt text"}),messages=locales.messages;locales.format,locales.useMessages;var DEBUG_PAYLOAD=/^(?:UNBOUND_DEBUG_COMPRESSED:)?ubd\d+:/;function readableDescriptions(descriptions){return descriptions.map(description=>description?.trim()??"").filter(description=>description&&!DEBUG_PAYLOAD.test(description)).map(description=>description.length>500?`${description.slice(0,500)}…`:description)}function withAltText(content,descriptions,label){var lines=descriptions.flatMap((description,index)=>[...content.length||index?[{type:"text",content:"\n"}]:[],{type:"em",content:[{type:"text",content:`${label}: ${description}`}]}]);return[...content,...lines]}function addAltText(row){var message=row?.message;if(message?.id&&message.channelId&&message.attachments?.length&&Array.isArray(message.content)){var source=unbound.flux.getStore("Message").getMessage(message.channelId,message.id),descriptions=readableDescriptions((source?.attachments??[]).map(attachment=>attachment.description));descriptions.length&&(message.content=withAltText(message.content,descriptions,messages.ALT_TEXT))}}return{start:function start(){unbound.metro.findByName("ChatManager")?unbound.metro.onModuleLoaded(unbound.metro.filters.byName("ChatManager"),ChatManager=>{"function"!=typeof ChatManager.prototype?.createRow?logger.warn("Image alt text skipped: Discord moved ChatManager.createRow."):unbound.patcher.after(ChatManager.prototype,"createRow",({result})=>{try{addAltText(result)}catch(error){logger.error("Failed to add alt text to a chat row:",error)}})}):logger.warn("Image alt text skipped: Discord moved ChatManager.")},stop:function stop(){unbound.patcher.unpatchAll()}}}();return this.__plugin;}})